import pypdf, re

base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_34/"
files = ["APPLE_2019_10K.pdf", "APPLE_2020_10K.pdf", "APPLE_2021_10K.pdf", "APPLE_2022_10K.pdf"]

for f in files:
    r = pypdf.PdfReader(base + f)
    hits = []
    for i, p in enumerate(r.pages):
        t = p.extract_text() or ""
        if re.search(r"CONSOLIDATED BALANCE SHEETS", t, re.I):
            hits.append((i, "BALANCE"))
        if re.search(r"CONSOLIDATED STATEMENTS OF OPERATIONS", t, re.I):
            hits.append((i, "OPS"))
    print(f, hits)
